      "reason": "Определяет существенные условия, но не перечисляет, какие нужно проверить."
    },
    {
      "doc": "D2",
      "grade": 3,
      "reason": "Дает конкретный перечень проверяемых сведений и условий трудового договора, включая должность, место работы, дату выхода, оклад и режим работы."
    },
    {
      "doc": "D3",
      "grade": 1,
      "reason": "Содержит общие определения договорных терминов без условий трудового договора."
    },
    {
      "doc": "D4",
      "grade": 2,
      "reason": "Частично указывает проверяемые поля: ФИО, даты, суммы, должности и реквизиты, но полного перечня условий не дает."
    },
    {
      "doc": "D5",
      "grade": 3,
      "reason": "Прямо перечисляет необходимые проверки условий и сведений трудового договора и источники их подтверждения."
    }
  ]
}

{
  "grades": [
    {
