      "grade": 3,
      "reason": "Прямо перечисляет документы, оформляемые водителем-экспедитором: путевые листы, ТТН, CMR и иные транспортные документы."
    },
    {
      "doc": "D2",
      "grade": 1,
      "reason": "Перечисляет связанные кадровые документы и политики, но не документы для рейса."
    },
    {
      "doc": "D3",
      "grade": 2,
      "reason": "Указывает, что путевой лист оформляется перед выездом, но не дает полного перечня оформляемых водителем документов."
    },
    {
      "doc": "D4",
      "grade": 2,
      "reason": "Называет путевой лист и транспортную накладную/CMR, но не уточняет, какие документы водитель оформляет перед рейсом."
    },
    {
      "doc": "D5",
      "grade": 1,
      "reason": "Описывает регистрацию и проверку авиагрузовой операции логистом или диспетчером, а не оформление документов водителем."
    }
  ]
}

{
  "grades": [
    {
