    },
    {
      "doc": "D4",
      "grade": 2,
      "reason": "Указывает отдельные проверки статуса работника, документов и расчета, но не раскрывает полный предметный перечень."
    },
    {
      "doc": "D5",
      "grade": 2,
      "reason": "Перечисляет часть проверяемых обстоятельств и документов, но не охватывает договор о полной ответственности, факт ущерба и объяснения работника."
    }
  ]
}
